(* [comment removed for export] *)
Ltac sk_rd SK MU WM a RD :=
  lazymatch type of SK with stack0 _ ?lo ?shi =>
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    let SKc := fresh "SKc" in
    assert (SKc : stack0 mc lo shi)
      by (eapply stack0_transport; [exact SK| exact MU| exact WM| apply Forall_cons; [apply stack0_ok_app; cbn [fst snd]; unfold AHI_LO; lia| apply Forall_nil]]);
    pose proof (stack0_read0_sr mc lo shi a 8 SKc ltac:(lia) ltac:(lia) ltac:(lia)) as RD; clear SKc
  end end.

