(* [comment removed for export] *)
Lemma rw_cells_CB0_intro : forall m A, 0 <= A <= 2^64 -> rw_cells bsegs m A [CB 0 []].
Proof.
  intros m A HA. split; [split; [cbn; split; [reflexivity| exact I]|]|].
  - split; [lia|]. split; [cbn; lia|]. intros i Hi. cbn in Hi. lia.
  - split; [lia|]. split; [cbn; lia|]. intros i Hi. cbn in Hi. lia.
Qed.
Lemma bytes_at_nil0 : forall m, bytes_at bsegs m 0 [].
Proof. intros m. split; [lia|]. split; [cbn; lia|]. intros i Hi. cbn in Hi. lia. Qed.
