(* [comment removed for export] *)
(* [comment removed for export] *)
Definition AEMPLACE_RET2 : Z := 0xc9b38.    (* [comment removed for export] *)
Definition AEMPLACE_RET3 : Z := 0xc4604.    (* [comment removed for export] *)

(* [comment removed for export] *)
Definition pb_frame (s2 s1 s0 ra : word) : list cell := [C8 s2; C8 s1; C8 s0; C8 ra].
Definition sl_frameA (j32 : list byte) (V : Z) (s4 s3 : word) : list cell :=
  [CB 32 j32; C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 V); C8 s4; C8 s3; C8 (Z_to_bv 64 0);
   C8 (Z_to_bv 64 (Z.shiftr (V + 8) 3 + 2147450880)); C8 (Z_to_bv 64 (V + 8)); C8 (Z_to_bv 64 AEMPLACE_RET3)].
Definition ct_frame (j8 : list byte) (V X : Z) (s5 : word) : list cell :=
  [CB 8 j8; C8 s5; C8 (Z_to_bv 64 2147450880); C8 (Z_to_bv 64 (Z.shiftr (V + 8) 3 + 2147450880)); C8 (Z_to_bv 64 X);
   C8 (Z_to_bv 64 V); C8 (Z_to_bv 64 (V + 8)); C8 (Z_to_bv 64 AEMPLACE_RET2)].

Definition eb_segA_post (sp gp tp s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (V X lo : Z) (s5 s4 s3 s2 s1 s0 ra : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' j32 j8,
    ms' = MS (mkR (Z_to_bv 64 AEMPLACE_RET1) (Z_to_bv 64 (bv_unsigned sp + -192)) gp tp t0 t1 t2
                  (Z_to_bv 64 (bv_unsigned sp + -96)) (Z_to_bv 64 1) (Z_to_bv 64 8) a1 a2 a3 a4 a5 a6 a7
                  (Z_to_bv 64 (bv_unsigned sp + -120)) (Z_to_bv 64 0)
                  (Z_to_bv 64 (Z.shiftr (bv_unsigned sp + -96) 3 + 2147450880)) (Z_to_bv 64 2147450880)
                  s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 AOPNEW) fc None m' (seg_rom bsegs)
    /\ munch [(bv_unsigned sp + -208, bv_unsigned sp)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp + -192)
    /\ rw_cells bsegs m' (bv_unsigned sp + -192) (ct_frame j8 V X s5)
    /\ rw_cells bsegs m' (bv_unsigned sp + -128) (sl_frameA j32 V s4 s3)
    /\ rw_cells bsegs m' (bv_unsigned sp + -32) (pb_frame s2 s1 s0 ra).

Lemma eb_segA : forall ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (V X lo shi : Z),
  rw_cells bsegs m V [C8 (wz 0); C8 (wz 0); C8 (wz 0)] -> V mod 8 = 0 -> accessible m V 24 -> aapp V 24 ->
  stk bsegs m lo (bv_unsigned sp) -> lo + 208 <= bv_unsigned sp -> aceil <= lo ->
  mem_inv bsegs m -> ACONST m -> stack0 m lo shi -> bv_unsigned sp <= shi ->
  evt bsegs (eb_segA_post sp gp tp s6 s7 s8 s9 s10 s11 F fc V X lo s5 s4 s3 s2 s1 s0 ra m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 V) (Z_to_bv 64 X) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
